def execute_command(image) -> List[ImagePatch]:
    image_patch = ImagePatch(image)
    car_patches = image_patch.find("white car")
    if not car_patches: 
        return image_patch

    # Sort cars based on their horizontal center
    car_patches.sort(key=lambda p: p.horizontal_center)

    # Check if the cars are organized by comparing their positions
    organized = all(car_patches[i].horizontal_center <= car_patches[i + 1].horizontal_center for i in range(len(car_patches) - 1))

    if organized:
        return car_patches
    else:
        return []

